# Group cells by color per block (block = rows 0-2 and 3-6, cols left/right of separator col7)
def blocks(di):
    B={}
    for i,r in enumerate(di):
        blk=i//3
        L=r[:7]; R=r[8:]
        for c,x in enumerate(L):
            if x!=0: B.setdefault(blk,[]).append((c,x))
        for c,x in enumerate(R):
            if x!=0: B.setdefault(blk,[]).append((7+c,x))
    return B
