def comps(g):
    H=len(g);W=len(g[0]);seen=[[False]*W for _ in range(H)];out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                col=g[i][j];stack=[(i,j)];cells=set()
                while stack:
                    y,z=stack.pop()
                    if (y,z) in cells or not(0<=y<H and 0<=z<W) or g[y][z]!=col: continue
                    cells.add((y,z))
                    for dy,dz in ((1,0),(-1,0),(0,1),(0,-1)): stack.append((y+dy,z+dz))
                r0=min(p[0] for p in cells); c0=min(p[1] for p in cells)
                pat=tuple(sorted((a-r0,b-c0) for a,b in cells))
                out.append({'col':col,'r0':r0,'c0':c0,'n':len(cells),'pat':pat})
    return out
