def comps_of(g, sep=4):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=set()
                while st:
                    a,b=st.pop(); cells.add((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            if da==db==0: continue
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==c:
                                seen[x][y]=True; st.append((x,y))
                out.append((cells,c))
    return out

