def transforms(g):
    res=[]
    for name,t in [('id',lambda g:g),('hflip',lambda g:[r[::-1] for r in g]),
                   ('vflip',lambda g:[r[::-1] for r in [g[::-1]]),('th',lambda g:[r[::-1] for r in g[::-1]]),
                   ('t',lambda g:[list(r) for r in zip(*g)]),('th',lambda g:[list(r) for r in zip(*g[::-1])])]:
        res.append((name,t))
    return res

